"""Actual-pixel source/old/new review; no generated anatomy or frame warping."""
import base64,json
from pathlib import Path
from PIL import Image,ImageDraw
ROOT=Path(__file__).resolve().parents[4];OUT=ROOT/'research/sprite-animation/leg-ownership-v16'
def uri(path):return 'data:image/png;base64,'+base64.b64encode(Path(path).read_bytes()).decode()
def matte(path):
 im=Image.open(path).convert('RGBA');bg=Image.new('RGBA',im.size,'#272727');bg.alpha_composite(im);return bg.convert('RGB')
def main():
 source=json.loads((ROOT/'research/sprite-animation/ground-walk-sixteen-v15/source/source-ground.json').read_text());old=[ROOT/f'research/sprite-animation/ground-walk-sixteen-v15/candidate/frames/{i:02}.png' for i in range(16)];new=[OUT/f'attempt3/frames/{i:02}.png' for i in range(16)]
 delays=json.loads((OUT/'attempt3/manifest.json').read_text())['gif_delays_ms'];frames=[];swatch=Image.new('RGB',(8*128,4*128))
 for i,(a,b) in enumerate(zip(old,new)):
  f=Image.new('RGB',(1024,540),'#272727');f.paste(matte(a),(0,28));f.paste(matte(b),(512,28));d=ImageDraw.Draw(f);d.text((8,8),'OLD: rejected sequence9-11 /600ms',fill='#ff9c9c');d.text((520,8),'NEW3: unapproved /600ms same clock',fill='#ffe4a0');frames.append(f)
  for j,p in enumerate([a,b]):n=i*2+j;swatch.paste(matte(p).resize((128,128)),(n%8*128,n//8*128))
 palette=swatch.quantize(colors=256,method=Image.Quantize.MEDIANCUT);gif=[f.quantize(palette=palette,dither=Image.Dither.NONE) for f in frames];gif[0].save(OUT/'old-vs-attempt3.gif',save_all=True,append_images=gif[1:],duration=delays,loop=0,disposal=2,optimize=False)
 board=Image.new('RGB',(1536,4*550),'#272727');d=ImageDraw.Draw(board)
 for row,k in enumerate([8,9,10,11]):
  for col,p in enumerate([ROOT/source['frames'][k]['cutaway_path'],old[k],new[k]]):board.paste(matte(p),(col*512,row*550+30))
  d.text((8,row*550+8),f'SOURCE {k+1}: LEFT near orange / RIGHT far blue',fill='white');d.text((520,row*550+8),'OLD USER-REJECTED SEQUENCE' if k<11 else 'OLD NEIGHBOR / unapproved',fill='#ff9c9c');d.text((1032,row*550+8),'NEW3: ownership still requires visual review',fill='#ffe4a0')
 board.save(OUT/'source-old-new-legs.png')
 reports={name:json.loads((OUT/'check'/file).read_text()) for name,file in [('old','old-standard-report.json'),('attempt2','new-standard-report.json'),('attempt3','attempt3-standard-report.json')]}
 data={'old':[uri(p) for p in old],'attempt2':[uri(OUT/f'candidate/frames/{i:02}.png') for i in range(16)],'attempt3':[uri(p) for p in new],'source':[uri(ROOT/f['dressed_path']) for f in source['frames']],'cutaway':[uri(ROOT/f['cutaway_path']) for f in source['frames']],'reports':{key:{'status':v['status'],'blockers':v['blockers'],'palette':v['stages']['continuity']['palette_patch_probe']} for key,v in reports.items()}}
 template='''<!doctype html><html lang="th"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sprite standard review</title><style>body{margin:0;padding:18px;background:#171b23;color:#eee;font:16px/1.5 system-ui}main{max-width:1440px;margin:auto}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:10px}figure{margin:0;background:#272727;padding:10px;min-width:0}img{width:100%;height:430px;object-fit:contain}button,select{font:inherit;padding:6px}input[type=range]{width:min(700px,90vw)}.warn{color:#ffc98b}.bad{color:#ff9999}h1{font-size:23px}h2{font-size:18px}</style><main><h1>มาตรฐานตรวจ sprite: source / anatomy / continuity</h1><p class="warn">ทุกชุดใหม่ยังไม่ผ่านการรับรองภาพ ขา น้ำหนัก และparts · ไม่ให้คะแนนหัวหรือพื้นแทนการตรวจทั้งตัว</p><button id="play">เล่น</button> <button id="next">ถัดไป</button> <select id="clock"><option value="600">600ms เท่ากัน</option><option value="1333">1333ms source clock</option><option value="2400">2400ms ตรวจช้า</option></select> <select id="attempt"><option value="attempt3">แก้รอบ3</option><option value="attempt2">รอบ2:ไม่รับเป็นseed</option></select> <label><input id="cutaway" type="checkbox" checked>แยกเจ้าของขาในsource</label><p><input id="phase" type="range" min="0" max="15" value="0"><output id="label"></output></p><p id="status" class="warn"></p><div class="grid"><figure><h2>Rigจริง:ซ้ายใกล้/ขวาไกล</h2><img id="source" alt="Actual source"></figure><figure><h2>ภาพเดิม</h2><img id="old" alt="Old16"></figure><figure><h2>ภาพทดลองใหม่</h2><img id="new" alt="New16"></figure></div><p id="metrics"></p><p id="blockers" class="warn"></p><p>phase9–11 เดิมถูกผู้ใช้ปฏิเสธเป็นกลุ่ม · ภาพใหม่ไม่รับคำอนุมัติเก่า · ทุกsampleใช้phaseจริงไม่ปัดเศษ · อ่านsource skeleton ไม่ใช่การวัดกระดูกที่ซ่อนในภาพใหม่</p></main><script>const data=DATA;let current=0,playing=false,start=0;const q=s=>document.querySelector(s);function show(i){current=(i+16)%16;q('#phase').value=current;const a=q('#attempt').value,r=data.reports[a],p=r.palette;q('#label').textContent='เฟรม '+(current+1)+' / source sample '+current*2.5;q('#source').src=(q('#cutaway').checked?data.cutaway:data.source)[current];q('#old').src=data.old[current];q('#new').src=data[a][current];const bad=current>=8&&current<=10;const warnings=(p.edges_over_declared_budget||[]).filter(e=>e.from===current||e.to===current);q('#status').textContent=(bad?'ภาพเดิม: REJECTED_SEQUENCE_MEMBER':'ภาพเดิม:ไม่ได้อนุมัติทั้งคลิป')+' · ภาพใหม่:'+r.status+(warnings.length?' · มีsurface-step warning':' · ไม่พบwarningที่จุดนี้ ไม่ใช่anatomy PASS');q('#status').className=bad?'bad':'warn';q('#metrics').textContent='พิกเซลกลุ่มผม: stepสูงสุด '+p.max_centroid_step_px.toFixed(1)+'px /16→1 '+p.last_to_first_centroid_step_px.toFixed(1)+'px · แค่surface proxy ไม่ใช่naturalnessหรือidentity';q('#blockers').textContent='ยังติด: '+r.blockers.join(' · ');}function stop(){playing=false;q('#play').textContent='เล่น'}q('#phase').oninput=()=>{stop();show(+q('#phase').value)};q('#next').onclick=()=>{stop();show(current+1)};q('#attempt').onchange=()=>show(current);q('#cutaway').onchange=()=>show(current);q('#clock').onchange=()=>start=performance.now()-current*(+q('#clock').value/16);q('#play').onclick=()=>{playing=!playing;start=performance.now()-current*(+q('#clock').value/16);q('#play').textContent=playing?'หยุด':'เล่น'};function tick(t){if(playing)show(Math.floor((t-start)/(+q('#clock').value/16))%16);requestAnimationFrame(tick)}show(0);requestAnimationFrame(tick);</script></html>'''
 template=template.replace('<option value="600">600ms เท่ากัน</option>','<option value="800">800ms /50msเท่ากันทุกเฟรม</option><option value="600">600ms เท่ากัน /control</option>')
 template=template.replace('body{margin:0;','body{overflow-wrap:anywhere;margin:0;').replace('width:min(700px,90vw)','width:min(700px,100%);box-sizing:border-box;margin-inline:0').replace('</style>','select{max-width:100%}</style>')
 (OUT/'frame-review.html').write_text(template.replace('DATA',json.dumps(data)));print('STANDARD_REVIEW real16 pixels/source/rejections/clock/seam')
if __name__=='__main__':main()
